import React, { useMemo, useState } from "react";
import "./MiniCalendar.css";

const DAY_LABELS = ["M", "T", "W", "T", "F", "S", "S"];

function buildGrid(year, monthIndex) {
  const first = new Date(year, monthIndex, 1);
  // JS getDay(): 0=Sun..6=Sat -> convert to Monday-first index
  const firstWeekday = (first.getDay() + 6) % 7;
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
  const daysInPrevMonth = new Date(year, monthIndex, 0).getDate();

  const cells = [];
  for (let i = firstWeekday - 1; i >= 0; i--) {
    cells.push({ day: daysInPrevMonth - i, current: false });
  }
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({ day: d, current: true });
  }
  while (cells.length % 7 !== 0 || cells.length < 42) {
    cells.push({ day: cells.length - (firstWeekday + daysInMonth) + 1, current: false });
    if (cells.length >= 42) break;
  }
  return cells;
}

export default function MiniCalendar({ selectedDate, onSelectDate }) {
  const initial = selectedDate || new Date();
  const [viewDate, setViewDate] = useState(new Date(initial.getFullYear(), initial.getMonth(), 1));

  const cells = useMemo(
    () => buildGrid(viewDate.getFullYear(), viewDate.getMonth()),
    [viewDate]
  );

  const monthLabel = viewDate.toLocaleDateString("en-US", { month: "long", year: "numeric" });
  const today = new Date();

  function isSelected(day, current) {
    if (!selectedDate || !current) return false;
    return (
      selectedDate.getDate() === day &&
      selectedDate.getMonth() === viewDate.getMonth() &&
      selectedDate.getFullYear() === viewDate.getFullYear()
    );
  }
  function isToday(day, current) {
    return (
      current &&
      today.getDate() === day &&
      today.getMonth() === viewDate.getMonth() &&
      today.getFullYear() === viewDate.getFullYear()
    );
  }

  return (
    <div className="mini-cal">
      <div className="mini-cal-header">
        <button onClick={() => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1))} aria-label="Previous month">‹</button>
        <span>{monthLabel}</span>
        <button onClick={() => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1))} aria-label="Next month">›</button>
      </div>
      <div className="mini-cal-grid mini-cal-labels">
        {DAY_LABELS.map((l, i) => (
          <span key={i}>{l}</span>
        ))}
      </div>
      <div className="mini-cal-grid">
        {cells.map((cell, idx) => (
          <button
            key={idx}
            className={[
              "mini-cal-cell",
              cell.current ? "" : "muted-cell",
              isSelected(cell.day, cell.current) ? "selected" : "",
              isToday(cell.day, cell.current) ? "today" : "",
            ].join(" ").trim()}
            onClick={() => cell.current && onSelectDate?.(new Date(viewDate.getFullYear(), viewDate.getMonth(), cell.day))}
          >
            {cell.day}
          </button>
        ))}
      </div>
    </div>
  );
}
